begin;
create function pg_temp.auction_claim(uid uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal','aal1')::text,true);end$$;
create function pg_temp.auction_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'AUCTION ASSERT: %',label;end if;end$$;
insert into auth.users(id,email,email_confirmed_at) values('98000000-0000-4000-8000-000000000001','auction-owner@example.invalid',now()),('98000000-0000-4000-8000-000000000002','auction-buyer@example.invalid',now());
do $$declare owner_id uuid:='98000000-0000-4000-8000-000000000001';buyer uuid:='98000000-0000-4000-8000-000000000002';sid uuid;pid uuid;ordered uuid;oid uuid;pic text;result jsonb;before_count int;begin
 perform pg_temp.auction_claim(owner_id);perform public.th_api('snapshot');perform pg_temp.auction_claim(buyer);perform public.th_api('snapshot');
 select id into sid from public.th_shops where user_id=owner_id;update public.th_shops set status='verified' where id=sid;
 pic:=owner_id::text||'/98000000-0000-4000-8000-000000000099.png';insert into public.th_uploads(path,user_id) values(pic,owner_id);
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode,bid_step,ends_at) values(sid,'Auction cancellation test','Auction management fixture','home','สภาพดี','Bangkok',pic,100,'auction',10,public.th_now()+3600000) returning id into pid;
 perform public.th_api('bid',jsonb_build_object('productId',pid,'amount',110,'requestKey','auction-cancel-bid-1'));
 begin perform public.th_api('auction_cancel',jsonb_build_object('productId',pid));raise exception 'Foreign owner accepted';exception when sqlstate 'PT404' then null;end;
 perform pg_temp.auction_claim(owner_id);
 begin perform public.th_api('auction_delete',jsonb_build_object('productId',pid));raise exception 'Active bids deleted';exception when sqlstate 'PT409' then null;end;
 result:=public.th_api('auction_cancel',jsonb_build_object('productId',pid));perform pg_temp.auction_assert((select status='withdrawn' and auction_cancelled_at is not null from public.th_products where id=pid),'cancel with bids');
 select count(*) into before_count from public.th_events where action='auction_cancel' and subject=pid::text;perform public.th_api('auction_cancel',jsonb_build_object('productId',pid));perform pg_temp.auction_assert((select count(*) from public.th_events where action='auction_cancel' and subject=pid::text)=before_count,'cancel retry no duplicate event');
 perform pg_temp.auction_claim(buyer);result:=public.th_api('snapshot');perform pg_temp.auction_assert(result#>>array['bids',pid::text,'status']='cancelled','bidder informed');
 begin perform public.th_api('bid',jsonb_build_object('productId',pid,'amount',120,'requestKey','auction-cancel-bid-2'));raise exception 'Bid after cancel accepted';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.auction_claim(owner_id);perform public.th_api('auction_delete',jsonb_build_object('productId',pid));result:=public.th_api('snapshot');perform pg_temp.auction_assert(not exists(select 1 from jsonb_array_elements(result->'products')x where x->>'id'=pid::text),'hidden from owner listings');
 perform pg_temp.auction_assert((select count(*) from public.th_bids where product_id=pid)=1,'bid evidence retained');perform public.th_api('auction_delete',jsonb_build_object('productId',pid));
 perform pg_temp.auction_claim(buyer);result:=public.th_api('snapshot');perform pg_temp.auction_assert(result#>>array['bids',pid::text,'title']='Auction cancellation test','deleted title retained in own bid history');
 perform set_config('request.jwt.claims','{}',true);result:=public.th_api('snapshot');perform pg_temp.auction_assert(not exists(select 1 from jsonb_array_elements(result->'products')x where x->>'id'=pid::text),'hidden publicly');
 begin perform public.th_api('auction_delete',jsonb_build_object('productId',pid));raise exception 'Anonymous accepted';exception when sqlstate 'PT401' then null;end;
 perform pg_temp.auction_claim(owner_id);
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode,ends_at) values(sid,'No bids','Auction management fixture','home','สภาพดี','Bangkok',pic,100,'auction',public.th_now()+3600000) returning id into pid;
 perform public.th_api('auction_delete',jsonb_build_object('productId',pid));perform pg_temp.auction_assert((select auction_deleted_at is not null from public.th_products where id=pid),'delete before any bid');
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode,ends_at) values(sid,'Ended with winning bid','Auction management fixture','home','สภาพดี','Bangkok',pic,100,'auction',public.th_now()-1000) returning id into ordered;
 insert into public.th_bids(product_id,user_id,amount,request_key) values(ordered,buyer,110,'auction-ended-bid-1');
 begin perform public.th_api('auction_cancel',jsonb_build_object('productId',ordered));raise exception 'Expired cancellation accepted';exception when sqlstate 'PT409' then null;end;
 perform public.th_api('snapshot');
 begin perform public.th_api('auction_delete',jsonb_build_object('productId',ordered));raise exception 'Order deleted';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.auction_assert((select reserved_order_id is not null from public.th_products where id=ordered),'winner order preserved');
end$$;
select 'Auction ownership, cancellation, retained bids, soft deletion and winner protection: PASS' as result;
rollback;
